mapper.select:
SELECT supplier AS name, COUNT(*) AS supplyNum, COUNT(DISTINCT category) AS categoryNum FROM bbx_restaurant_inbound_record WHERE supplier IS NOT NULL and deleted = 1
and tenant_id =#{tenantId}
GROUP BY supplier ORDER BY supplyNum DESC LIMIT 1

SELECT TO_CHAR(inbound_time, 'MM') AS time, category, COALESCE(SUM(inbound_quantity), 0) AS inboundQty FROM bbx_restaurant_inbound_record WHERE inbound_time >= #{minDay} AND inbound_time <= #{maxDay} AND category IS NOT NULL AND inbound_quantity IS NOT NULL AND inbound_quantity >= 0 and deleted = 1
and tenant_id =#{tenantId}
GROUP BY TO_CHAR(inbound_time, 'MM'), category
